INSERT INTO _s495_hermas_m VALUES
('hermas-23-the-angel-of-punishment-and-the-pleasure-that-ends-in-death',23,1,'canon','deuteronomy',30,16,1,$n$Deuteronomy 30:16 — *to walk in his ways, and to keep his commandments and his statutes and his judgments, that thou mayest live and multiply* Walk in the commandments and live, as it was first set before Yashar'el.$n$),
('hermas-23-the-angel-of-punishment-and-the-pleasure-that-ends-in-death',23,2,'canon','1-timothy',5,6,2,$n$1 Timothy 5:6 — *But she that liveth in pleasure is dead while she liveth.* A life given over to pleasure is already death.$n$),
('hermas-23-the-angel-of-punishment-and-the-pleasure-that-ends-in-death',23,3,'canon','psalms',119,71,3,$n$Psalm 119:71 — *It is good for me that I have been afflicted; that I might learn thy statutes.* Affliction that teaches the statutes of Yahuah.$n$),
('hermas-23-the-angel-of-punishment-and-the-pleasure-that-ends-in-death',23,4,'canon','hebrews',11,25,4,$n$Hebrews 11:25 — *Choosing rather to suffer affliction with the people of Elohim (God), than to enjoy the pleasures of sin for a season* The pleasures of sin last only for a season.$n$),
('hermas-24-the-head-of-the-house-afflicted-and-the-household-repents',24,1,'canon','psalms',51,17,1,$n$Psalm 51:17 — *a broken and a contrite heart, O Elohim (God), thou wilt not despise.* Elohim does not despise a broken and contrite heart.$n$),
('hermas-24-the-head-of-the-house-afflicted-and-the-household-repents',24,1,'canon','leviticus',26,3,2,$n$Leviticus 26:3 — *If ye walk in my statutes, and keep my commandments, and do them;* The covenant word on walking in the commandments and doing them, with its blessing to follow.$n$);
